entries[16870] = { ["name"] = "Freizaubern", ["text"] = "100 Meter Reichweite\nSofort\nJeder Eurer Schadens- und Heilzauber gewährt eine Chance, Euch in einen Freizauberzustand zu versetzen. Der Freizauberzustand verringert die Mana-, Wut- oder Energiekosten Eures nächsten Schadens- oder Heilzaubers mit Zauberzeit oder Eurer nächsten Offensivfähigkeit um 100%.\n\nWenn Ihr auf 'Wilder Kampf' spezialisiert seid, wird der Effekt 'Omen der Klarheit' auch von Euren automatischen Angriffen ausgelöst werden." }
