entries[16880] = { ["name"] = "Anmut der Natur", ["text"] = "Wenn Ihr Eure Zauber 'Mondfeuer', 'Nachwachsen' oder 'Insektenschwarm' wirkt, gewinnt Ihr 15 Sek. lang 5% Zaubertempo. Dieser Effekt hat 1 Min. Abklingzeit. Wenn Ihr eine Mond- oder Sonnenfinsternis erreicht, wird die Abklingzeit von 'Anmut der Natur' sofort abgeschlossen." }
