entries[16973] = { ["name"] = "Verzauberter Kampfhammer", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nThoriumbarren (20), Verzauberter Thoriumbarren (6), Gewaltiger Smaragd (2), Mächtiges Mojo (4), Unverwüstliches Leder (4)\nVerzauberter Kampfhammer\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n100 - 150 Schaden Tempo 2.60\n(48.08 Schaden pro Sekunde)\nHaltbarkeit 100 / 100\n51\nAnlegen: Erhöht Eure Parierwertung um 20.\nAnlegen: Erhöht die Trefferwertung um 20." }
entries[16974] = { ["name"] = "Raubtierschläge", ["text"] = "Erhöht die kritische Trefferchance Eurer Fähigkeit 'Verheeren' bei Zielen, die über mehr als 80% Gesundheit verfügen, um 50%.\n\nEure Finishing-Moves gewähren pro Combopunkt eine Chance von 20%, dass Euer nächster gewirkter Naturzauber mit Zauberzeit, dessen Basiszauberzeit weniger als 10 Sek. beträgt, zu einem kostenlosen Spontanzauber wird." }
entries[16978] = { ["name"] = "Loderflammenrapier", ["text"] = "Wirken in 45 sek.\nTools: Schmiedehammer\nReagenzien:\nVerzauberter Thoriumbarren (10), Essenz des Feuers (4), Herz des Feuers (4), Azerothischer Diamant (2), Verdichteter Schleifstein (2)\nLoderflammenrapier\nWird beim Anlegen gebunden\nEinhändig Schwert\n44 - 82 Schaden Tempo 1.70\n(37.06 Schaden pro Sekunde)\nHaltbarkeit 90 / 90\n51\nTrefferchance: Verbrennt den Feind und fügt ihm im Verlauf von 30 Sek. 100 Schaden zu." }
entries[16979] = { ["name"] = "Wilde Attacke", ["text"] = "5 Wut 8 - 25 Meter Reichweite\nSpontanzauber 15 sek. Abklingzeit\nBenötigt Bärengestalt\nStürmt auf einen Gegner zu und macht ihn 4 Sek. lang bewegungsunfähig." }
